SELECT 
FROM xxl_job_openapi_callback AS t
WHERE t.log_id = #{logId}

SELECT 
FROM xxl_job_openapi_callback AS t
WHERE t.status = 0
AND t.next_retry_time <= #{now}
AND t.retry_count < #{maxRetry}
ORDER BY t.next_retry_time ASC
LIMIT #{pagesize}

mapper.update:
UPDATE xxl_job_openapi_callback
SET status = #{newStatus}
WHERE log_id = #{logId}
AND status = #{oldStatus}

UPDATE xxl_job_openapi_callback
SET retry_count = retry_count + 1,
	next_retry_time = #{newNextRetryTime}
WHERE log_id = #{logId}
AND status = 0
AND next_retry_time = #{oldNextRetryTime}

UPDATE xxl_job_openapi_callback
SET next_retry_time = #{nextRetryTime}
WHERE log_id = #{logId}
AND status = 0
